import{_ as a,o as e,a as d,b as o}from"./app.BGziXukh.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/programming_guide"},{"text":"调试调优","link":"/guide/programming_guide/debug_and_tuning/debug_and_tuning"},{"text":"性能调优","link":"/guide/programming_guide/debug_and_tuning/performance_tuning"}]},"headers":[],"relativePath":"guide/programming_guide/debug_and_tuning/performance_tuning.md","filePath":"guide/programming_guide/debug_and_tuning/performance_tuning.md","outlineHeaders":[{"level":2,"title":"性能采集与分析工具","slug":"性能采集与分析工具","link":"#性能采集与分析工具"},{"level":2,"title":"NPU域上板性能分析","slug":"NPU域上板性能分析","link":"#NPU域上板性能分析"},{"level":2,"title":"NPU域仿真性能分析","slug":"NPU域仿真性能分析","link":"#NPU域仿真性能分析"}],"lastUpdated":1795158538000}'),i={name:"guide/programming_guide/debug_and_tuning/performance_tuning.md"};function s(n,t,r,c,p,l){return e(),d("div",null,[...t[0]||(t[0]=[o(`<div><article class="markdown-body"><h1>性能调优<span id="ZH-CN_TOPIC_0000002529073929"></span></h1><h2 id="性能采集与分析工具">性能采集与分析工具<span id="section20894115120010"></span><a class="header-anchor" href="#性能采集与分析工具">​</a></h2><p>通过毕昇编译器编译生成可执行程序后，使用msOpProf工具采集Ascend C算子在AI处理器上执行的性能数据，进行性能精细调优。</p><p><a href="https://gitcode.com/Ascend/msopprof/blob/master/docs/zh/user_guide/msopprof_user_guide.md">msOpProf工具</a>包含msopprof和msopprof simulator两种使用方式，协助用户定位算子内存、算子代码以及算子指令的异常，实现全方位的算子调优。两种使用方式的详细说明请参考表1。</p><p><strong>表1 msopprof和msopprof simulator功能说明表</strong></p><table><thead><tr><th>功能名称</th><th>适用场景</th><th>使用方式</th><th>展示的图形</th></tr></thead><tbody><tr><td>msopprof</td><td>适用于上板性能分析（实际运行环境中的性能分析），可协助用户定位算子内存和性能瓶颈。</td><td>直接分析运行中的算子，无需额外配置，适合在板环境中快速定位算子性能问题。</td><td>计算内存热力图<br>Roofline瓶颈分析图<br>Cache热力图<br>通算流水图<br>算子代码热点图</td></tr><tr><td>msopprof simulator</td><td>适用于仿真性能分析，可协助用户分析算子指令和代码热点问题。</td><td>需要参考msopprof simulator配置，配置环境变量（如LD_LIBRARY_PATH）和编译选项（如添加-g生成调试信息），适合在仿真环境中详细分析算子行为。</td><td>指令流水图<br>算子代码热点图<br>内存通路吞吐率波形图</td></tr></tbody></table><h2 id="NPU域上板性能分析">NPU域上板性能分析<span id="section107378341021"></span><a class="header-anchor" href="#NPU域上板性能分析">​</a></h2><p>算子程序通过毕昇编译器编译生成可执行程序后，可以通过msopprof在NPU上完成性能采集。以SIMD编程场景为例，使用msOpProf工具采集上板性能数据大致步骤如下：</p><ol><li><p>参考<a href="../compilation_and_execution/operator_compilation/ai_core_operator_compilation.html">AI Core SIMD编译</a>，编译add算子样例，生成可执行文件。</p><p>dav-后为NPU架构版本号，请根据实际情况进行替换，各产品型号对应的架构版本号请通过<a href="../language_extension/simd_builtin_keywords.html#npu-arch">对应关系表</a>进行查询。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>bisheng add_custom.asc -o add_custom --npu-arch=dav-2201
</code></pre></div></li><li><p>使用msopprof调用算子可执行文件进行性能采集。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>msopprof ./add_custom
</code></pre></div></li><li><p>查看性能数据，了解当前算子性能瓶颈。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>性能数据文件夹结构示例：
OPPROF_{timestamp}_XXX
├──dump                       # 原始的性能数据，用户无需关注
├──ArithmeticUtilization.csv  # cube/vector指令cycle占比，建议优化算子逻辑，减少冗余计算指令
├──L2Cache.csv                # L2 Cache命中率，影响MTE2，建议合理规划数据搬运逻辑，增加命中率
├──Memory.csv                 # Unified Buffer（UB），L1和主存储器读写带宽速率，单位GB/s
├──MemoryL0.csv               # L0A，L0B，和L0C读写带宽速率，单位GB/s
├──MemoryUB.csv               # Vector和Scalar到UB的读写带宽速率，单位GB/s
├──OpBasicInfo.csv            # 算子基础信息
├──PipeUtilization.csv        # pipe类指令耗时和占比，建议优化数据搬运逻辑，提高带宽利用率
├──ResourceConflictRatio.csv  # UB上的bank group、bank conflict和资源冲突率在所有指令中的占比，建议减少/避免对于同一个bank读写冲突或bank group的读读冲突
└──visualize_data.bin         # MindStudio Insight呈现文件
</code></pre></div></li></ol><p><strong>表2 msopprof文件介绍</strong><span id="table244174535419"></span></p><table><thead><tr><th>名称</th><th>说明</th></tr></thead><tbody><tr><td>dump文件夹</td><td>原始的性能数据，用户无需关注。</td></tr><tr><td>ArithmeticUtilization.csv</td><td>Cube和Vector类型的指令耗时和占比，可参考ArithmeticUtilization（Cube及Vector类型指令耗时和占比）。</td></tr><tr><td>L2Cache.csv</td><td>L2 Cache命中率，可参考L2Cache（L2 Cache命中率）。</td></tr><tr><td>Memory.csv</td><td>UB/L1/L2/主存储器采集内存读写带宽速率，可参考Memory（内存读写带宽速率）。</td></tr><tr><td>MemoryL0.csv</td><td>L0A/L0B/L0C采集内存读写带宽速率，可参考MemoryL0（L0读写带宽速率）。</td></tr><tr><td>MemoryUB.csv</td><td>mte/vector/scalar采集UB读写带宽速率，可参考MemoryUB（UB读写带宽速率）。</td></tr><tr><td>PipeUtilization.csv</td><td>采集计算单元和搬运单元耗时和占比，可参考PipeUtilization（计算单元和搬运单元耗时占比）。</td></tr><tr><td>ResourceConflictRatio.csv</td><td>UB上的bank group、bank conflict和资源冲突在所有指令中的占比，可参考ResourceConflictRatio（资源冲突占比）。</td></tr><tr><td>OpBasicInfo.csv</td><td>算子基础信息，包含算子名称、block dim和耗时等信息，可参考OpBasicInfo（算子基础信息）。</td></tr><tr><td>visualize_data.bin</td><td>算子基础信息、计算单元负载、热点函数和Roofline瓶颈分析等信息的可视化呈现文件。visualize_data.bin可通过MindStudio Insight工具进行可视化展示。</td></tr><tr><td>trace.json</td><td>通算流水可视化呈现文件，Chrome浏览器具体请参考通算流水图。</td></tr></tbody></table><p>对于SIMT编程场景，只需遵循<a href="../compilation_and_execution/operator_compilation/ai_core_operator_compilation.html">AI Core SIMT编译</a>指导进行算子编译，生成可执行文件后，按照上述步骤2和步骤3使用msOpProf工具执行程序，以获取算子执行的性能数据。</p><h2 id="NPU域仿真性能分析">NPU域仿真性能分析<span id="section75259502193"></span><a class="header-anchor" href="#NPU域仿真性能分析">​</a></h2><p>在非昇腾设备上，通过毕昇编译器仿真编译后生成可执行程序，可以通过msopprof simulator完成性能流水仿真。当前仅支持SIMD编程场景，SIMT编程场景不支持。</p><ul><li><p><strong>通过CMake方式仿真编译算子</strong></p><ul><li><p>灵活控制不同的target是否开启仿真编译。修改CMakeList，使用target_link_libraries与target_link_directories手动配置链接库与路径：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>find_package(ASC REQUIRED)
project(kernel_samples LANGUAGES ASC)

add_executable(demo
    add_custom.asc
)

set_target_properties(demo PROPERTIES 
    LINK_FLAGS &quot;-Wl,--disable-new-dtags&quot;  ## 由于仿真库会依赖当前目录的其他非链接的so，需要开启RPATH传递依赖目录
)

target_link_libraries(demo PRIVATE
    runtime_camodel npu_drv_camodel  ## 仿真编译需要链接的so
    m
)

# \${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。以root用户安装为例，安装后文件默认存储路径为：/usr/local/Ascend/cann。
target_link_directories(demo PRIVATE
    \${INSTALL_DIR}/tools/simulator/dav_2201/lib  ##仿真库所在的目录，其中dav_2201目录名称与芯片版本相关 
)

target_compile_options(demo PRIVATE
    $&lt;$&lt;COMPILE_LANGUAGE:ASC&gt;: --npu-arch=dav-2201&gt;
)
</code></pre></div><p>其中仿真库所在目录与NPU架构版本号之间的关系如下，目录名使用<strong>下划线</strong>连接“dav”和架构版本号。</p><p>其中仿真编译所依赖的库介绍如下，开启仿真编译时，需要优先链接，确保优先使用仿真库的符号，防止出现运行时coredump等异常情况。</p><p><strong>表3 仿真编译依赖库介绍</strong><span id="table84131311195116"></span></p><table><thead><tr><th>名称</th><th>作用描述</th></tr></thead><tbody><tr><td>libruntime_camodel.so</td><td>camodel仿真运行时库，负责NPU算子仿真环境的运行时功能支持。</td></tr><tr><td>libnpu_drv_camodel.so</td><td>仿真驱动库，对真实的驱动接口打桩，模拟真实NPU驱动行为，提供硬件交付的接口仿真。</td></tr></tbody></table></li><li><p>通过向CMake传入变量CMAKE_ASC_RUN_MODE和CMAKE_ASC_ARCHITECTURES来统一开启仿真编译。命令示例如下：</p><p>sim表示开启仿真编译，dav-后为NPU架构版本号，请根据实际情况进行填写。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake -B build -DCMAKE_ASC_RUN_MODE=sim -DCMAKE_ASC_ARCHITECTURES=dav-2201
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>使用命令行往CMake传入变量的方式全局生效，会对CMakeList中所有的target开启sim模式。</p></div></li></ul></li><li><p><strong>通过命令行方式仿真编译算子可执行程序</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code># 编译算子: bisheng  [算子源文件] -o [输出产物名称] --npu-arch=[NPU架构版本号]，--run-mode=sim
bisheng add_custom.asc -o add_custom --npu-arch=dav-2201 --run-mode=sim
</code></pre></div></li><li><p><strong>性能流水仿真</strong></p><p>使用msopprof simulator并获取仿真数据。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>msopprof simulator --soc-version=Ascendxxxyy ./add_custom
</code></pre></div><p>仿真数据说明</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>OPPROF_{timestamp}_XXX
├──dump                    # 原始的性能数据，用户无需关注
└──simulator               # 算子基础信息
   ├──core0.cubecore0
   ├──...
   ├──core23.cubecore0
   ├──trace.json           # Edge/Chrome Trace Viewer/Perfetto呈现文件
   └──visualize_data.bin   # MindStudio Insight呈现文件
</code></pre></div></li></ul><p><strong>表4 msopprof simulator文件介绍</strong></p><table><thead><tr><th>名称</th><th>说明</th></tr></thead><tbody><tr><td>dump文件夹</td><td>原始仿真生成的dump数据存放文件夹。</td></tr><tr><td>core*_code_exe.csv</td><td>代码行耗时，*代表0~n核，以便用户快速确定编写的代码中最耗时的部分，可参考代码行耗时数据文件。</td></tr><tr><td>core*_instr_exe.csv</td><td>代码指令详细信息，*代表0~n核，以便用户快速确定最耗时的指令，可参考代码指令信息文件。</td></tr><tr><td>visualize_data.bin</td><td>仿真流水图和仿真热点函数等信息可视化呈现文件。</td></tr><tr><td>trace.json</td><td>仿真指令流水图文件，包括每个核的子文件以及全部核的汇总文件，可参考指令流水图和内存通路吞吐率波形图。</td></tr></tbody></table><p>更多详细的信息可以参考<a href="https://gitcode.com/Ascend/msopprof/blob/master/docs/zh/user_guide/msopprof_user_guide.md">《msOpProf用户指南》</a>。</p></article></div>`,1)])])}const g=a(i,[["render",s]]);export{v as __pageData,g as default};
